// ─── File: AntiJoinDemo.java ───
// Anti-join + the LEFT JOIN WHERE-condition trap and the ON-clause fix.
package com.bank.antijoin;

import java.util.*;
import java.util.logging.*;

public class AntiJoinDemo {
    private static final Logger log = Logger.getLogger(AntiJoinDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BankRepository repo = new BankRepository();
        CustomerFilterService service = new CustomerFilterService(repo);

        log.info("=== Anti-join: customers with NO transactions ===");
        service.customersWithNoTxn().forEach(id -> log.info("no txn: " + id));

        log.info("=== TRAP: status='FAILED' AND IS NULL in WHERE (impossible) ===");
        List<String> trap = service.trapImpossibleWhere();
        if (trap.isEmpty())
            log.severe("Returned 0 rows: status='FAILED' needs a row, IS NULL needs none!");

        log.info("=== CORRECT: no FAILED txn (status moved into ON) ===");
        service.customersWithNoFailedTxn().forEach(id -> log.info("no failed: " + id));
    }
}

// ─── Would be in model/Customer.java ───
class Customer {
    final String id, name;
    Customer(String id, String name) { this.id = id; this.name = name; }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, customerId, status;
    Txn(String id, String cust, String status) {
        this.txnId = id; this.customerId = cust; this.status = status;
    }
}

// ─── Would be in repository/BankRepository.java ───
class BankRepository {
    List<Customer> customers() {
        return List.of(new Customer("C1", "Rajesh Kumar"),
                       new Customer("C2", "Priya Sharma"),
                       new Customer("C3", "Amit Verma"));
    }
    List<Txn> txns() {
        return List.of(
            new Txn("T1", "C1", "FAILED"),
            new Txn("T2", "C1", "SUCCESS"),
            new Txn("T3", "C2", "SUCCESS"));
    }
}

// ─── Would be in service/CustomerFilterService.java ───
class CustomerFilterService {
    private final BankRepository repo;
    CustomerFilterService(BankRepository repo) { this.repo = repo; }

    // Anti-join: LEFT JOIN then keep where right key IS NULL (no match).
    List<String> customersWithNoTxn() {
        List<String> result = new ArrayList<>();
        for (Customer c : repo.customers()) {
            boolean hasAny = repo.txns().stream().anyMatch(t -> t.customerId.equals(c.id));
            if (!hasAny) result.add(c.id); // t.txn_id IS NULL
        }
        return result;
    }

    // TRAP: status='FAILED' AND txn_id IS NULL — contradictory, always empty.
    List<String> trapImpossibleWhere() {
        List<String> result = new ArrayList<>();
        for (Customer c : repo.customers()) {
            for (Txn t : matchOrNull(c)) {
                // WHERE t.status='FAILED' AND t.txn_id IS NULL
                boolean statusFailed = "FAILED".equals(t == null ? null : t.status);
                boolean keyIsNull = (t == null);
                if (statusFailed && keyIsNull) result.add(c.id); // can never be both
            }
        }
        return result;
    }

    // CORRECT: status moved into ON — match only FAILED txns, keep unmatched customers.
    List<String> customersWithNoFailedTxn() {
        List<String> result = new ArrayList<>();
        for (Customer c : repo.customers()) {
            // ON c.id = t.customer_id AND t.status = 'FAILED'
            boolean hasFailed = repo.txns().stream()
                .anyMatch(t -> t.customerId.equals(c.id) && "FAILED".equals(t.status));
            if (!hasFailed) result.add(c.id); // t.txn_id IS NULL after restricted join
        }
        return result;
    }

    // helper: LEFT JOIN rows for a customer (matched rows, or a single null placeholder)
    private List<Txn> matchOrNull(Customer c) {
        List<Txn> matches = repo.txns().stream()
            .filter(t -> t.customerId.equals(c.id)).toList();
        if (matches.isEmpty()) { List<Txn> l = new ArrayList<>(); l.add(null); return l; }
        return matches;
    }
}

